#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import base64, hashlib, json, shutil, subprocess, sys, zlib

ROOT = Path.cwd()
PAYLOADS = {'academyControllers.js': {'sha256': '76b8233780765f1d3bc7a9cb4d18108464c712c6f07a15a2bf94c271c27d6388', 'data': ''}, 'backend/repositories/academySupabaseRepo.js': {'sha256': 'e2f42ff3b1826cd7f83051e029279f84ff6133cbf22b9529b3ae7d7b5805764d', 'data': ''}, 'public/js/academy.js': {'sha256': '88d189ce02b5c2cb18e461ff48ef47e078049546e0e071010c94cac787d94f08', 'data': ''}, 'public/academy.html': {'sha256': '6f94e7040ad95eee47f83c345ae0f9a5f7e51d4422cf4cee4b899ab0dfb1c227', 'data': ''}}

def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()

stamp = datetime.now().strftime('%Y%m%d-%H%M%S')
backups = []

try:
    for rel, spec in PAYLOADS.items():
        path = ROOT / rel
        if not path.exists():
            raise FileNotFoundError(f'Missing required file: {path}')
        current = path.read_bytes()
        current_hash = sha256_bytes(current)
        if current_hash != spec['sha256']:
            raise RuntimeError(
                f'{rel}: current file does not match the audited post-3C.6 version. '
                f'Expected {spec["sha256"][:12]}, got {current_hash[:12]}.'
            )
        backup = path.with_name(path.name + f'.backup-phase-3c6b-{stamp}')
        shutil.copy2(path, backup)
        backups.append((path, backup))

    for rel, spec in PAYLOADS.items():
        path = ROOT / rel
        patched = zlib.decompress(base64.b64decode(spec['data']))
        path.write_bytes(patched)

    checks = [
        ['node', '--check', str(ROOT / 'academyControllers.js')],
        ['node', '--check', str(ROOT / 'backend/repositories/academySupabaseRepo.js')],
        ['node', '--check', str(ROOT / 'public/js/academy.js')],
    ]
    for command in checks:
        result = subprocess.run(command, cwd=ROOT, capture_output=True, text=True)
        if result.returncode != 0:
            raise RuntimeError('Syntax check failed:\n' + result.stdout + result.stderr)

    print('Phase 3C.6B legacy Roadmap migration patched successfully.')
    print('Updated: academyControllers.js')
    print('Updated: backend/repositories/academySupabaseRepo.js')
    print('Updated: public/js/academy.js')
    print('Updated: public/academy.html')
    print('Syntax checks: passed')
    for _, backup in backups:
        print(f'Backup: {backup}')

except Exception as error:
    for original, backup in backups:
        if backup.exists():
            shutil.copy2(backup, original)
    print(f'Patch failed and backups were restored: {error}', file=sys.stderr)
    sys.exit(1)